// ============================================================================
//  MULTI-CLINICA
//  Este nodo ya no da por hecho que solo existe una clinica. Cruza cada cita
//  con su clinica para saber tres cosas:
//    - desde que numero de WhatsApp hay que enviar (telefono_whatsapp_id)
//    - en que zona horaria vive esa clinica        (zona_horaria)
//    - como se llama, para que el mensaje lo diga  (nombre)
//
//  Dar de alta una clinica nueva = insertar una fila en la tabla clinicas.
//  Este codigo NO se toca nunca mas.
// ============================================================================

// AVISO: las clinicas hay que leerlas POR EL NOMBRE del nodo.
// $input aqui devuelve las CITAS (el nodo inmediatamente anterior), no las
// clinicas. Es el mismo fallo que rompio el workflow 04 en agosto.
const clinicas = new Map(
  $('Cargar clinicas').all()
    .map(item => item.json || {})
    .filter(c => c.id)
    .map(c => [c.id, c])
);

const ZONA_POR_DEFECTO = 'Europe/Madrid';

// "Manana" no es la misma fecha para todas las clinicas: depende de su zona.
// Una clinica espanola y una portuguesa pueden estar en dias distintos a las
// 00:30. Por eso se calcula una vez por zona, no una vez para todos.
const calcularManana = zona => {
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: zona,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  }).formatToParts(new Date(Date.now() + 24 * 60 * 60 * 1000));
  const get = tipo => parts.find(p => p.type === tipo).value;
  return get('year') + '-' + get('month') + '-' + get('day');
};

const cacheManana = new Map();
const manana = zona => {
  if (!cacheManana.has(zona)) cacheManana.set(zona, calcularManana(zona));
  return cacheManana.get(zona);
};

// Supabase devuelve booleanos reales. Aceptamos tambien los textos 'no'/'false'
// que venian de Google Sheets, por si queda alguna fila migrada a mano.
const pendienteDeEnviar = v => v === false
  || v === null
  || v === undefined
  || ['no', 'false', ''].includes(v.toString().toLowerCase().trim());

// La columna fecha es de tipo date: Supabase la devuelve como 'YYYY-MM-DD'.
const normFecha = f => {
  if (!f) return '';
  const v = f.toString().trim();
  const iso = v.match(/^(\d{4})-(\d{2})-(\d{2})/);
  return iso ? iso[1] + '-' + iso[2] + '-' + iso[3] : v;
};

// La busqueda de Supabase trae de mas a proposito (desde ayer en adelante) y
// quien decide que cita toca es este codigo, que si conoce la zona de cada
// clinica. Filtrar por la fecha exacta de manana en la consulta fallaria con
// clinicas en husos distintos.
//
// AVISO: el nodo de Supabase de n8n NO admite dos condiciones sobre la misma
// columna: la segunda pisa a la primera. Por eso hay un solo filtro de fecha
// y el limite superior lo pone este codigo, no la consulta.
return $input.all()
  .map(item => item.json || {})
  .map(row => ({ row, clinica: clinicas.get(row.clinica_id) }))
  .filter(({ row, clinica }) => {
    // Sin clinica, desactivada o sin numero de WhatsApp no se envia nada.
    if (!clinica || clinica.activo === false) return false;
    if (!clinica.telefono_whatsapp_id) return false;

    const zona     = clinica.zona_horaria || ZONA_POR_DEFECTO;
    const estado   = (row.estado || '').toString().toLowerCase().trim();
    const telefono = (row.telefono || '').toString().trim();

    return normFecha(row.fecha) === manana(zona)
      && estado === 'confirmada'
      && pendienteDeEnviar(row.recordatorio_24h)
      && telefono !== ''
      && !!row.event_id;
  })
  .map(({ row, clinica }) => ({
    json: {
      ...row,
      eventId:        row.event_id,
      telefono:       row.telefono.toString(),
      // Lo lee el nodo "Enviar recordatorio". Cada clinica envia desde SU numero.
      phoneNumberId:  clinica.telefono_whatsapp_id,
      clinicaNombre:  clinica.nombre,
      respuesta: 'Hola ' + (row.nombre || '') + ', te recordamos que tienes una cita de '
        + (row.tratamiento || 'tu tratamiento') + ' manana a las ' + row.hora
        + ' en ' + (clinica.nombre || 'la clinica')
        + '. Si no puedes asistir, puedes cancelar o cambiar la cita por aqui.'
    }
  }));
